sourceTypography.declarations:
margin: 0;
  background: var(--background);
  color: var(--foreground);
  font: 17px/1.6 var(--font-body);
  -webkit-font-smoothing: antialiased;

display: inline-flex;
  align-items: center;
  min-height: 44px;
  font-size: 15px;
  border-bottom: 1px solid transparent;
  transition: border-color 180ms var(--ease-out);

display: inline-flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  min-height: 46px;
  padding: 10px 18px;
  border-radius: 6px;
  background: var(--accent);
  color: var(--foreground);
  font-size: 14px;
  font-weight: 600;
  transition: background-color 180ms var(--ease-out);

display: inline-flex;
  align-items: center;
  justify-content: space-between;
  gap: 35px;
  min-height: 54px;
  padding: 14px 21px;
  border-radius: 6px;
  background: var(--accent);
  color: var(--foreground);
  font-size: 16px;
  font-weight: 600;
  transition: background-color 180ms var(--ease-out);
